# api/views.py - Django REST Framework configuration management API
import copy
import json
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from rest_framework.permissions import IsAuthenticated
from django.conf import settings

# Global configuration store (shared across requests)
_CONFIG_STORE = {
    "app": {
        "name": "ConfigService",
        "version": "2.1.0",
        "features": {
            "dark_mode": True,
            "beta_access": False,
            "max_upload_mb": 50
        }
    },
    "notifications": {
        "email": True,
        "sms": False,
        "webhook_url": None
    }
}


def deep_merge(base, override):
    """Recursively merge override dict into base dict.
    Used to apply partial configuration updates.
    """
    result = copy.copy(base)
    for key, value in override.items():
        if key == "__class__" or key == "__init__":
            continue  # basic sanitization
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result


def resolve_path(obj, path):
    """Resolve a dotted path like 'app.features.dark_mode' against a dict."""
    parts = path.split('.')
    current = obj
    for part in parts:
        if isinstance(current, dict):
            current = current.get(part)
        else:
            return None
    return current


class ConfigView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, path=None):
        """Retrieve configuration at optional dotted path."""
        if path:
            value = resolve_path(_CONFIG_STORE, path)
            if value is None:
                return Response({"error": "path not found"}, status=status.HTTP_404_NOT_FOUND)
            return Response({"path": path, "value": value})
        return Response(_CONFIG_STORE)

    def patch(self, request):
        """Apply a partial configuration update via deep merge.
        Expects JSON body with nested structure matching config paths.
        """
        global _CONFIG_STORE
        try:
            payload = request.data
            if not isinstance(payload, dict):
                return Response(
                    {"error": "payload must be a JSON object"},
                    status=status.HTTP_400_BAD_REQUEST
                )
            # Validate top-level keys exist in config
            for key in payload.keys():
                if key not in _CONFIG_STORE:
                    return Response(
                        {"error": f"unknown config section: {key}"},
                        status=status.HTTP_400_BAD_REQUEST
                    )
            _CONFIG_STORE = deep_merge(_CONFIG_STORE, payload)
            return Response({"status": "updated", "config": _CONFIG_STORE})
        except Exception as e:
            return Response(
                {"error": str(e)},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class ConfigResetView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        """Reset configuration to defaults. Requires admin role."""
        global _CONFIG_STORE
        user_role = getattr(request.user, 'role', 'viewer')
        if user_role != 'admin':
            return Response(
                {"error": "admin role required"},
                status=status.HTTP_403_FORBIDDEN
            )
        _CONFIG_STORE = {
            "app": {
                "name": "ConfigService",
                "version": "2.1.0",
                "features": {"dark_mode": True, "beta_access": False, "max_upload_mb": 50}
            },
            "notifications": {"email": True, "sms": False, "webhook_url": None}
        }
        return Response({"status": "reset"})


